-- postgres/durable schema. Safe to apply more than once: every object uses
-- IF NOT EXISTS or CREATE OR REPLACE, and statuses are text with CHECK
-- constraints instead of enum types. Table changes still need new migrations.
-- Requires PostgreSQL 16+. IDs are generated by the application.

CREATE SCHEMA IF NOT EXISTS durable;

-- Fencing tokens for everything except resource leases. Never reset it.
CREATE SEQUENCE IF NOT EXISTS durable.fencing_seq;

-- ---------------------------------------------------------------------------
-- Resource leases. Rows are permanent fencing history: never delete them.
-- Throughout this schema a NULL lease/expiry time means "no lease".
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS durable.leases (
    namespace  text        NOT NULL,
    key        text        NOT NULL,
    owner_id   text,
    token      bigint      NOT NULL DEFAULT 0 CHECK (token >= 0),
    expires_at timestamptz,
    PRIMARY KEY (namespace, key),
    CHECK (namespace <> '' AND key <> '')
);

-- Nonwaiting acquisition. The advisory gate serializes first-row inserts; a
-- hash collision can cause brief spurious contention, never two owners.
CREATE OR REPLACE FUNCTION durable.acquire_lease(
    p_namespace text, p_key text, p_owner text, p_ttl_us bigint
) RETURNS bigint LANGUAGE plpgsql AS $$
DECLARE
    v_row durable.leases%ROWTYPE;
    v_now timestamptz;
BEGIN
    IF NOT pg_try_advisory_xact_lock(hashtextextended(
        json_build_array('durable.leases', p_namespace, p_key)::text, 0)) THEN
        RETURN 0;
    END IF;
    SELECT * INTO v_row FROM durable.leases
    WHERE namespace = p_namespace AND key = p_key FOR UPDATE NOWAIT;
    IF NOT FOUND THEN
        INSERT INTO durable.leases (namespace, key)
        VALUES (p_namespace, p_key) RETURNING * INTO v_row;
    END IF;
    v_now := clock_timestamp();
    IF v_row.owner_id IS NOT NULL AND v_row.expires_at > v_now THEN
        RETURN 0;
    END IF;
    IF v_row.token = 9223372036854775807 THEN
        RAISE EXCEPTION 'durable: lease token exhausted' USING ERRCODE = '22003';
    END IF;
    UPDATE durable.leases
    SET owner_id = p_owner, token = v_row.token + 1,
        expires_at = v_now + p_ttl_us * interval '1 microsecond'
    WHERE namespace = p_namespace AND key = p_key;
    RETURN v_row.token + 1;
EXCEPTION WHEN lock_not_available THEN
    RETURN 0;
END;
$$;

-- Expiry is checked after the row lock, so lock waiting cannot revive a lease.
CREATE OR REPLACE FUNCTION durable.renew_lease(
    p_namespace text, p_key text, p_owner text, p_token bigint, p_ttl_us bigint
) RETURNS boolean LANGUAGE plpgsql AS $$
DECLARE
    v_row durable.leases%ROWTYPE;
    v_now timestamptz;
BEGIN
    SELECT * INTO v_row FROM durable.leases
    WHERE namespace = p_namespace AND key = p_key FOR UPDATE;
    v_now := clock_timestamp();
    IF NOT FOUND OR v_row.owner_id IS DISTINCT FROM p_owner
        OR v_row.token <> p_token OR v_row.expires_at <= v_now THEN
        RETURN false;
    END IF;
    UPDATE durable.leases
    SET expires_at = v_now + p_ttl_us * interval '1 microsecond'
    WHERE namespace = p_namespace AND key = p_key;
    RETURN true;
END;
$$;

-- Bounds the current transaction (statement, lock, idle and, on 17+,
-- transaction timeouts) to p_timeout, e.g. '2000ms'.
CREATE OR REPLACE FUNCTION durable.set_local_timeouts(p_timeout text)
RETURNS void LANGUAGE plpgsql AS $$
BEGIN
    PERFORM set_config(s.name, p_timeout, true) FROM pg_settings s
    WHERE s.name IN ('statement_timeout', 'lock_timeout',
                     'idle_in_transaction_session_timeout', 'transaction_timeout');
END;
$$;

-- Run after promoting a replica or restoring a backup, before workers resume.
-- Moves every token domain past anything that may have been issued but lost.
CREATE OR REPLACE FUNCTION durable.advance_fencing(p_gap bigint DEFAULT 1000000000)
RETURNS void LANGUAGE plpgsql AS $$
BEGIN
    IF p_gap <= 0 THEN
        RAISE EXCEPTION 'durable: gap must be positive';
    END IF;
    PERFORM setval('durable.fencing_seq',
        (SELECT last_value FROM durable.fencing_seq) + p_gap);
    UPDATE durable.leases SET token = token + p_gap;
END;
$$;

-- ---------------------------------------------------------------------------
-- Generic lease functions. Each feature keeps its own table; these functions
-- perform every ownership transition on any table that has the lease
-- columns, so the fencing rules live in one place:
--
--   id uuid (unique), status text, owner_id text, token bigint,
--   lease_expires_at timestamptz, updated_at timestamptz
--   and, when used: run_at timestamptz, attempts integer,
--   max_attempts integer, last_error text
--
-- Features select candidate rows themselves (with their own filters and
-- FOR UPDATE SKIP LOCKED) and pass the IDs in. Expiry is always evaluated
-- with clock_timestamp() after the row is locked. Tokens come from
-- durable.fencing_seq. Check a table with durable.lease_contract().
-- ---------------------------------------------------------------------------

-- Reports the lease columns a table is missing (empty when it conforms).
CREATE OR REPLACE FUNCTION durable.lease_contract(p_table regclass, p_full boolean)
RETURNS SETOF text LANGUAGE sql STABLE AS $$
    SELECT c.col FROM unnest(CASE WHEN p_full
        THEN ARRAY['id', 'status', 'owner_id', 'token', 'lease_expires_at', 'updated_at',
                   'run_at', 'attempts', 'max_attempts', 'last_error']
        ELSE ARRAY['id', 'status', 'owner_id', 'token', 'lease_expires_at', 'updated_at'] END) AS c(col)
    WHERE NOT EXISTS (SELECT 1 FROM pg_attribute a
                      WHERE a.attrelid = p_table AND a.attname = c.col
                        AND a.attnum > 0 AND NOT a.attisdropped);
$$;

-- Grants new leases on the given rows that are claimable: status is
-- p_ready_status or p_running_status, run_at has passed, and there is no
-- live owner. With p_count_attempt, attempts is incremented and rows that
-- used up max_attempts are skipped. Each row gets its own token.
CREATE OR REPLACE FUNCTION durable.lease_grant(
    p_table regclass, p_ids uuid[], p_owner text, p_ttl_us bigint,
    p_ready_status text, p_running_status text, p_count_attempt boolean
) RETURNS TABLE (id uuid, token bigint, attempts integer)
LANGUAGE plpgsql AS $$
BEGIN
    RETURN QUERY EXECUTE format($q$
        UPDATE %s t
        SET status = $5, owner_id = $2, token = nextval('durable.fencing_seq'),
            lease_expires_at = clock_timestamp() + $3 * interval '1 microsecond',
            %s updated_at = now()
        WHERE t.id = ANY($1) AND t.run_at <= clock_timestamp()
          AND t.status IN ($4, $5)
          AND (t.owner_id IS NULL OR t.lease_expires_at <= clock_timestamp())
          %s
        RETURNING t.id, t.token, %s$q$,
        p_table,
        CASE WHEN p_count_attempt THEN 'attempts = t.attempts + 1,' ELSE '' END,
        CASE WHEN p_count_attempt THEN 'AND t.attempts < t.max_attempts' ELSE '' END,
        CASE WHEN p_count_attempt THEN 't.attempts' ELSE '0' END)
    USING p_ids, p_owner, p_ttl_us, p_ready_status, p_running_status;
END;
$$;

-- Extends a live lease. False means the lease is lost (owner, token or
-- status changed, or it already expired): stop working.
CREATE OR REPLACE FUNCTION durable.lease_renew(
    p_table regclass, p_id uuid, p_owner text, p_token bigint,
    p_running_status text, p_ttl_us bigint
) RETURNS boolean LANGUAGE plpgsql AS $$
DECLARE
    v_n integer;
BEGIN
    EXECUTE format($q$
        UPDATE %s t
        SET lease_expires_at = clock_timestamp() + $5 * interval '1 microsecond', updated_at = now()
        WHERE t.id = $1 AND t.owner_id = $2 AND t.token = $3 AND t.status = $4
          AND t.lease_expires_at > clock_timestamp()$q$, p_table)
    USING p_id, p_owner, p_token, p_running_status, p_ttl_us;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    RETURN v_n = 1;
END;
$$;

-- Locks the row (FOR UPDATE) and reports whether this owner still holds it.
-- Call it first in a transaction that then writes feature columns: once it
-- returns true, no successor can take the row until the transaction ends.
-- p_require_unexpired=false is only for callers that already hold the row
-- lock from an earlier statement in the same transaction.
CREATE OR REPLACE FUNCTION durable.lease_lock(
    p_table regclass, p_id uuid, p_owner text, p_token bigint,
    p_running_status text, p_require_unexpired boolean
) RETURNS boolean LANGUAGE plpgsql AS $$
DECLARE
    v_ok boolean;
BEGIN
    EXECUTE format($q$
        SELECT t.owner_id = $2 AND t.token = $3 AND t.status = $4
               AND (NOT $5 OR t.lease_expires_at > clock_timestamp())
        FROM %s t WHERE t.id = $1 FOR UPDATE$q$, p_table)
    INTO v_ok USING p_id, p_owner, p_token, p_running_status, p_require_unexpired;
    RETURN coalesce(v_ok, false);
END;
$$;

-- Ends a lease with a new status, clearing owner and lease. Optional parts:
-- p_delay_us (NULL keeps run_at), p_last_error (NULL keeps it, '' clears it),
-- p_attempt_delta (0 keeps attempts; -1 gives an attempt back).
-- p_require_unexpired=false only while the caller holds the row lock.
CREATE OR REPLACE FUNCTION durable.lease_finish(
    p_table regclass, p_id uuid, p_owner text, p_token bigint,
    p_running_status text, p_require_unexpired boolean,
    p_status text, p_delay_us bigint, p_last_error text, p_attempt_delta integer
) RETURNS boolean LANGUAGE plpgsql AS $$
DECLARE
    v_n integer;
BEGIN
    EXECUTE format($q$
        UPDATE %s t
        SET status = $6, owner_id = NULL, lease_expires_at = NULL, updated_at = now()
            %s %s %s
        WHERE t.id = $1 AND t.owner_id = $2 AND t.token = $3 AND t.status = $4
          AND (NOT $5 OR t.lease_expires_at > clock_timestamp())$q$,
        p_table,
        CASE WHEN p_delay_us IS NULL THEN ''
             ELSE ', run_at = clock_timestamp() + $7 * interval ''1 microsecond''' END,
        CASE WHEN p_last_error IS NULL THEN '' ELSE ', last_error = nullif($8, '''')' END,
        CASE WHEN p_attempt_delta = 0 THEN '' ELSE ', attempts = t.attempts + $9' END)
    USING p_id, p_owner, p_token, p_running_status, p_require_unexpired,
          p_status, p_delay_us, p_last_error, p_attempt_delta;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    RETURN v_n = 1;
END;
$$;

-- Moves an expired lease (owner presumed dead) to p_status, prefixing
-- last_error with p_reason. Matching owner and token makes it safe against
-- a concurrent renewal or a successor.
CREATE OR REPLACE FUNCTION durable.lease_expire(
    p_table regclass, p_id uuid, p_owner text, p_token bigint,
    p_running_status text, p_status text, p_reason text
) RETURNS boolean LANGUAGE plpgsql AS $$
DECLARE
    v_n integer;
BEGIN
    EXECUTE format($q$
        UPDATE %s t
        SET status = $5, owner_id = NULL, lease_expires_at = NULL, updated_at = now(),
            last_error = CASE WHEN $6 = '' THEN t.last_error ELSE concat_ws(': ', $6, t.last_error) END
        WHERE t.id = $1 AND t.owner_id = $2 AND t.token = $3 AND t.status = $4
          AND t.lease_expires_at <= clock_timestamp()$q$, p_table)
    USING p_id, p_owner, p_token, p_running_status, p_status, p_reason;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    RETURN v_n = 1;
END;
$$;

-- ---------------------------------------------------------------------------
-- Idempotency keys: synchronous requests (in_flight/completed/failed) and
-- keys linked to an execution (linked).
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS durable.idempotency_keys (
    id               uuid        NOT NULL DEFAULT gen_random_uuid() UNIQUE,
    scope            text        NOT NULL,
    key              text        NOT NULL,
    request          jsonb       NOT NULL,
    status           text        NOT NULL
        CHECK (status IN ('in_flight', 'completed', 'failed', 'linked')),
    owner_id         text,
    token            bigint      NOT NULL DEFAULT 0,
    lease_expires_at timestamptz,
    response         jsonb,
    execution_id     uuid,
    expires_at       timestamptz NOT NULL,
    created_at       timestamptz NOT NULL DEFAULT now(),
    updated_at       timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (scope, key),
    CHECK (scope <> '' AND key <> '')
);
CREATE INDEX IF NOT EXISTS idempotency_keys_expires_at_idx
    ON durable.idempotency_keys (expires_at);
CREATE INDEX IF NOT EXISTS idempotency_keys_execution_idx
    ON durable.idempotency_keys (execution_id) WHERE execution_id IS NOT NULL;

-- Returns outcome: acquired, in_flight, completed, failed, linked, mismatch.
CREATE OR REPLACE FUNCTION durable.begin_key(
    p_scope text, p_key text, p_request jsonb, p_owner text,
    p_lease_us bigint, p_retention_us bigint
) RETURNS TABLE (outcome text, key_id uuid, token bigint, response jsonb, execution_id uuid)
LANGUAGE plpgsql AS $$
#variable_conflict use_column
DECLARE
    v_row durable.idempotency_keys%ROWTYPE;
    v_now timestamptz := clock_timestamp();
    v_token bigint;
    v_id uuid;
BEGIN
    LOOP
        SELECT * INTO v_row FROM durable.idempotency_keys k
        WHERE k.scope = p_scope AND k.key = p_key FOR UPDATE;
        v_now := clock_timestamp();
        IF NOT FOUND OR v_row.expires_at <= v_now THEN
            v_token := nextval('durable.fencing_seq');
            BEGIN
                INSERT INTO durable.idempotency_keys AS k (scope, key, request, status,
                    owner_id, token, lease_expires_at, expires_at)
                VALUES (p_scope, p_key, p_request, 'in_flight', p_owner, v_token,
                    v_now + p_lease_us * interval '1 microsecond',
                    v_now + p_retention_us * interval '1 microsecond')
                ON CONFLICT ON CONSTRAINT idempotency_keys_pkey DO UPDATE
                SET request = EXCLUDED.request, status = 'in_flight',
                    owner_id = EXCLUDED.owner_id, token = EXCLUDED.token,
                    lease_expires_at = EXCLUDED.lease_expires_at, response = NULL,
                    execution_id = NULL, expires_at = EXCLUDED.expires_at,
                    created_at = now(), updated_at = now()
                WHERE k.expires_at <= clock_timestamp()
                RETURNING k.id INTO v_id;
                IF FOUND THEN
                    RETURN QUERY SELECT 'acquired'::text, v_id, v_token, NULL::jsonb, NULL::uuid;
                    RETURN;
                END IF;
            EXCEPTION WHEN unique_violation THEN
                NULL; -- lost an insert race; read the winner's row
            END;
            CONTINUE;
        END IF;
        IF v_row.request <> p_request THEN
            RETURN QUERY SELECT 'mismatch'::text, v_row.id, 0::bigint, NULL::jsonb, NULL::uuid;
            RETURN;
        END IF;
        IF v_row.status IN ('completed', 'failed', 'linked') THEN
            RETURN QUERY SELECT v_row.status, v_row.id, v_row.token, v_row.response, v_row.execution_id;
            RETURN;
        END IF;
        IF v_row.lease_expires_at > v_now THEN
            RETURN QUERY SELECT 'in_flight'::text, v_row.id, 0::bigint, NULL::jsonb, NULL::uuid;
            RETURN;
        END IF;
        v_token := nextval('durable.fencing_seq');
        UPDATE durable.idempotency_keys k
        SET owner_id = p_owner, token = v_token,
            lease_expires_at = v_now + p_lease_us * interval '1 microsecond',
            updated_at = now()
        WHERE k.scope = p_scope AND k.key = p_key;
        RETURN QUERY SELECT 'acquired'::text, v_row.id, v_token, NULL::jsonb, NULL::uuid;
        RETURN;
    END LOOP;
END;
$$;

-- ---------------------------------------------------------------------------
-- Executions (jobs).
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS durable.executions (
    id               uuid        PRIMARY KEY,
    queue            text        NOT NULL,
    kind             text        NOT NULL,
    scope            text,
    key              text,
    payload          jsonb       NOT NULL,
    payload_version  integer     NOT NULL DEFAULT 1 CHECK (payload_version > 0),
    mode             text        CHECK (mode IN ('tx', 'activity')), -- fixed at the first claim
    status           text        NOT NULL
        CHECK (status IN ('pending', 'running', 'succeeded', 'failed', 'cancelled')),
    attempts         integer     NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    max_attempts     integer     NOT NULL CHECK (max_attempts > 0),
    run_at           timestamptz NOT NULL,
    owner_id         text,
    token            bigint      NOT NULL DEFAULT 0,
    lease_expires_at timestamptz,
    cancel_requested boolean     NOT NULL DEFAULT false,
    checkpoint_name  text        NOT NULL DEFAULT '',
    checkpoint_data  jsonb,
    last_error       text,
    output           jsonb,
    created_at       timestamptz NOT NULL DEFAULT now(),
    updated_at       timestamptz NOT NULL DEFAULT now(),
    finished_at      timestamptz
);
CREATE INDEX IF NOT EXISTS executions_pending_idx
    ON durable.executions (queue, run_at) WHERE status = 'pending';
CREATE INDEX IF NOT EXISTS executions_running_idx
    ON durable.executions (queue, lease_expires_at) WHERE status = 'running';
CREATE INDEX IF NOT EXISTS executions_finished_idx
    ON durable.executions (finished_at) WHERE finished_at IS NOT NULL;
CREATE INDEX IF NOT EXISTS executions_key_idx
    ON durable.executions (scope, key) WHERE key IS NOT NULL;

CREATE TABLE IF NOT EXISTS durable.execution_steps (
    execution_id uuid        NOT NULL REFERENCES durable.executions (id) ON DELETE CASCADE,
    name         text        NOT NULL,
    remote_key   text        NOT NULL,
    request      jsonb       NOT NULL,
    response     jsonb,
    status       text        NOT NULL CHECK (status IN ('started', 'done')),
    updated_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (execution_id, name)
);

CREATE TABLE IF NOT EXISTS durable.execution_attempts (
    execution_id uuid        NOT NULL REFERENCES durable.executions (id) ON DELETE CASCADE,
    attempt      integer     NOT NULL,
    owner_id     text        NOT NULL,
    token        bigint      NOT NULL,
    started_at   timestamptz NOT NULL DEFAULT now(),
    finished_at  timestamptz,
    outcome      text,
    error        text,
    PRIMARY KEY (execution_id, attempt)
);

-- ---------------------------------------------------------------------------
-- Outbox. Unordered events are queue rows. Ordered events get a gapless seq
-- per (topic, aggregate_key) from outbox_heads; the relay leases a stream.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS durable.outbox_events (
    id               uuid        PRIMARY KEY,
    topic            text        NOT NULL,
    type             text        NOT NULL,
    aggregate_key    text,        -- set only on ordered topics
    seq              bigint,      -- gapless per (topic, aggregate_key)
    partition_key    text,        -- broker partition hint on unordered topics
    headers          jsonb       NOT NULL DEFAULT '{}',
    payload          jsonb       NOT NULL,
    is_gap           boolean     NOT NULL DEFAULT false,
    status           text        NOT NULL DEFAULT 'pending'
        CHECK (status IN ('pending', 'running', 'published', 'dead')),
    attempts         integer     NOT NULL DEFAULT 0,
    max_attempts     integer     NOT NULL DEFAULT 10 CHECK (max_attempts > 0),
    run_at           timestamptz NOT NULL DEFAULT now(),
    owner_id         text,
    token            bigint      NOT NULL DEFAULT 0,
    lease_expires_at timestamptz,
    last_error       text,
    created_at       timestamptz NOT NULL DEFAULT now(),
    updated_at       timestamptz NOT NULL DEFAULT now(),
    published_at     timestamptz,
    UNIQUE (topic, aggregate_key, seq),
    CHECK ((aggregate_key IS NULL) = (seq IS NULL))
);
CREATE INDEX IF NOT EXISTS outbox_events_unordered_idx
    ON durable.outbox_events (run_at)
    WHERE aggregate_key IS NULL AND status IN ('pending', 'running');
CREATE INDEX IF NOT EXISTS outbox_events_ordered_idx
    ON durable.outbox_events (topic, aggregate_key, seq)
    WHERE aggregate_key IS NOT NULL AND status = 'pending';
CREATE INDEX IF NOT EXISTS outbox_events_published_idx
    ON durable.outbox_events (published_at) WHERE published_at IS NOT NULL;

CREATE TABLE IF NOT EXISTS durable.outbox_heads (
    topic         text   NOT NULL,
    aggregate_key text   NOT NULL,
    head_seq      bigint NOT NULL,
    PRIMARY KEY (topic, aggregate_key)
);

CREATE TABLE IF NOT EXISTS durable.outbox_streams (
    id                 uuid        NOT NULL DEFAULT gen_random_uuid() UNIQUE,
    topic              text        NOT NULL,
    aggregate_key      text        NOT NULL,
    last_published_seq bigint      NOT NULL DEFAULT 0,
    status             text        NOT NULL DEFAULT 'active'
        CHECK (status IN ('active', 'blocked', 'stopped')),
    attempts           integer     NOT NULL DEFAULT 0,
    run_at             timestamptz NOT NULL DEFAULT now(),
    owner_id           text,
    token              bigint      NOT NULL DEFAULT 0,
    lease_expires_at   timestamptz,
    last_error         text,
    updated_at         timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (topic, aggregate_key)
);

-- ---------------------------------------------------------------------------
-- Inbox.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS durable.inbox_messages (
    source        text        NOT NULL,
    message_id    text        NOT NULL,
    aggregate_key text,
    seq           bigint,
    version       bigint,
    status        text        NOT NULL
        CHECK (status IN ('applied', 'buffered', 'enqueued', 'skipped')),
    execution_id  uuid,
    received_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (source, message_id)
);
CREATE INDEX IF NOT EXISTS inbox_messages_received_idx
    ON durable.inbox_messages (source, received_at);

-- Stream positions are never purged while the stream is alive.
CREATE TABLE IF NOT EXISTS durable.inbox_streams (
    source           text        NOT NULL,
    aggregate_key    text        NOT NULL,
    last_applied_seq bigint      NOT NULL DEFAULT 0,
    last_version     bigint,
    gap_since        timestamptz,
    updated_at       timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (source, aggregate_key)
);

CREATE TABLE IF NOT EXISTS durable.inbox_pending (
    source        text        NOT NULL,
    aggregate_key text        NOT NULL,
    seq           bigint      NOT NULL,
    message_id    text        NOT NULL,
    type          text        NOT NULL DEFAULT '',
    payload       jsonb,
    is_gap        boolean     NOT NULL DEFAULT false,
    received_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (source, aggregate_key, seq)
);

-- ---------------------------------------------------------------------------
-- Schedules.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS durable.schedules (
    name              text        PRIMARY KEY,
    spec              text        NOT NULL,
    time_zone         text        NOT NULL DEFAULT 'UTC',
    queue             text        NOT NULL,
    kind              text        NOT NULL,
    payload           jsonb       NOT NULL DEFAULT '{}',
    missed            text        NOT NULL DEFAULT 'latest'
        CHECK (missed IN ('all', 'latest', 'none')),
    overlap           text        NOT NULL DEFAULT 'skip'
        CHECK (overlap IN ('skip', 'queue', 'allow')),
    paused            boolean     NOT NULL DEFAULT false,
    next_run_at       timestamptz NOT NULL,
    last_run_at       timestamptz,
    last_execution_id uuid,
    updated_at        timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS schedules_due_idx
    ON durable.schedules (next_run_at) WHERE NOT paused;

-- ---------------------------------------------------------------------------
-- Cache. UNLOGGED: contents are disposable and not replicated.
-- ---------------------------------------------------------------------------
CREATE UNLOGGED TABLE IF NOT EXISTS durable.cache (
    key                text        PRIMARY KEY,
    value              jsonb,
    version            bigint      NOT NULL DEFAULT 0,
    expires_at         timestamptz,
    stale_until        timestamptz,
    compute_owner      text,
    compute_expires_at timestamptz,
    updated_at         timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS cache_stale_until_idx ON durable.cache (stale_until);
